import { PERSONALITY_TRAITS, traitPointBudget, traitPoints, personalityTrait, personalityView, personalitySelectionReason, natureEdition } from './personality.js';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// A nature is a trade-off on a new life; only older saves still carry the
// attribute points a trait once bought.
export function traitBonusesLabel(t,state=null){return state&&!natureEdition(state)?Object.entries(t.attributes).map(([key,n])=>`+${n} ${key[0].toUpperCase()+key.slice(1)}`).join(' · '):t.acquired?'Written by life':'A trade-off, not a bonus';}
export function renderTraitPicker(ids,age,{creation=true,state=null}={}){
 const budget=traitPointBudget(age),remaining=budget-traitPoints(ids),slots=Array.from({length:3},(_,i)=>personalityTrait(ids[i]));
 return `<section class="personality-builder" aria-label="Personality traits"><div class="section-heading"><h3 tabindex="-1">Your Nature</h3><span class="badge" data-trait-points>${ids.length} / 3 traits</span></div><div class="trait-slots">${slots.map((t,i)=>t?`<div class="trait-slot filled"><strong>${e(t.name)}</strong><small>${e(traitBonusesLabel(t,state))}</small>${creation?`<button type="button" class="trait-remove" data-op="creator-trait" data-id="${t.id}" aria-label="Remove ${e(t.name)}">×</button>`:''}<p>${e(t.description)}</p></div>`:`<button type="button" class="trait-slot empty" data-op="trait-picker" data-id="${i}" ${age<3||remaining<1?'disabled':''} aria-label="Choose trait for slot ${i+1}"><span aria-hidden="true">+</span><small>${age<3?'Develops as you grow':'Add Trait'}</small></button>`).join('')}</div>${ids.length>3?`<p class="small-copy">Earlier traits remain: ${ids.slice(3).map(id=>e(personalityTrait(id)?.name||id)).join(', ')}. Your saved nature is retained.</p>`:''}<p class="small-copy">${age<3?'Nature develops after infancy.':'Choose up to three compatible traits. Conflicting traits cannot be paired.'}</p><details class="nature-rules"><summary>How Your Nature Affects Choices</summary><p>${state&&!natureEdition(state)?'Traits grant their listed attributes. ':'Some choices exist only for some natures, and people hold you by what their own people respect. '}Choices against a trait add 6 stress, up to 12 per decision, once per day; choices in harmony relieve up to 4, once per week. ${creation?'You may leave a slot open.':state&&natureEdition(state)?'Life writes the rest: how you cope when you break, what hunger makes of you, and what years of choosing otherwise do to a trait.':'Chosen traits are lasting.'}</p></details>${state?renderAcquired(state):''}</section>`;
}
function renderAcquired(state){const rows=personalityView(state).acquired;if(!rows.length)return '';return `<div class="trait-slots trait-marks" aria-label="What life has written">${rows.map(t=>`<div class="trait-slot filled"><strong>${e(t.name)}</strong><small>Since age ${Math.max(0,Math.floor((t.day-(state.timeline?.birthDay||0))/365))}</small><p>${e(t.description)}</p></div>`).join('')}</div>`;}
export function renderTraitSelection(ids,age,{creation=true,state=null}={}){
 const remaining=traitPointBudget(age)-traitPoints(ids);
 return `<h2 id="trait-picker-heading">Choose a Trait</h2><p>Choose one for an open slot. The list shows conflicts and age restrictions before selection.</p><div class="trait-selection-list">${PERSONALITY_TRAITS.map(t=>{
 const selected=ids.includes(t.id),opposed=ids.includes(t.opposite),reason=selected?'Already selected.':ids.length>=3?'All three slots are filled.':creation?(opposed?`Conflicts with ${personalityTrait(t.opposite).name}.`:remaining<t.cost?'More nature develops as you grow.':''):personalitySelectionReason(state,t.id);
 return `<button type="button" class="trait-option" data-op="${creation?'creator-trait':'personality-trait'}" data-id="${t.id}" ${reason?'disabled':''}><span><strong>${e(t.name)}</strong><small>${e(traitBonusesLabel(t,state))}</small><span>${e(t.description)}</span>${reason?`<small class="trait-reason">${e(reason)}</small>`:''}</span><span aria-hidden="true">${selected?'✓':'+'}</span></button>`;
 }).join('')}</div>`;
}
export function renderPersonalityPanel(state){const p=personalityView(state);return `<section class="panel personality-panel"><div class="section-heading"><h2>Personality &amp; Composure</h2><span class="badge">Stress ${p.stress}/100</span></div>${renderTraitPicker(p.ids,state.age,{creation:false,state})}${p.history.length?`<details><summary>Recent Choices &amp; Stress</summary>${p.history.slice(-8).reverse().map(h=>`<p>${e(h.text)}</p>`).join('')}</details>`:''}</section>`;}
